Projection.ArtifactTemplate:
{% for e in evidence %}- evidenceUri: {{ e.evidenceUri }} learning record
  uri: {{ e.slots.recordUri }}
  kind: {{ e.slots.kind }}
  summary: {{ e.slots.summary }}
  sourceRefs: {{ e.slots.sourceRefs }}
  matchedBy: {{ e.slots.matchedBy }}
{% endfor %}

{% for e in evidence %}- evidenceUri: {{ e.evidenceUri }} temporal digest
  uri: {{ e.slots.digestRef }}
  granularity: {{ e.slots.granularity }}
  period: {{ e.slots.periodStart }} / {{ e.slots.periodEnd }}
  summary: {{ e.slots.summary }}
  topics: {{ e.slots.topics }}
  openLoops: {{ e.slots.openLoops }}
  sourceRefs: {{ e.slots.sourceRefs }}
{% endfor %}
